(3389404, 471291, 74273, '<td valign="top">nice composition</td>', 'nice composition', '2007-02-21 11:52:29.000000', NULL, 1),
(3389407, 470453, 47852, '<td valign="top">Nicely done with the tight crop.  I think this one might work better if it had a different color background to offset the color of the hands a little more.  Also seems like there is a slight halo around the hands, especially to the left side.  A product of resize or sharpening?</td>', 'Nicely done with the tight crop.  I think this one might work better if it had a different color background to offset the color of the hands a little more.  Also seems like there is a slight halo around the hands, especially to the left side.  A product of resize or sharpening?', '2007-02-21 11:52:53.000000', NULL, 1),
(3389409, 472568, 61552, '<td valign="top">Is this purposely grainy?</td>', 'Is this purposely grainy?', '2007-02-21 11:53:20.000000', NULL, 1),
(3389413, 472418, 47852, '<td valign="top">Nicely done.. I like the b/w tones here, but the child''s arm almost gets lost into the bright background.  Thanks for cleaning up under the fingernails first.. nothing worse than dirty fingernails in a picture!</td>', 'Nicely done.. I like the b/w tones here, but the child''s arm almost gets lost into the bright background.  Thanks for cleaning up under the fingernails first.. nothing worse than dirty fingernails in a picture!', '2007-02-21 11:54:11.000000', NULL, 1),
(3389417, 472248, 47852, '<td valign="top">Nice depiction of love... The background it just a tad too bright for me since you''re losing parts of the shoulders and her hips into the white, and it''s also very contrasty (is that a word?) compared to the shadows of her face.</td>', 'Nice depiction of love... The background it just a tad too bright for me since you''re losing parts of the shoulders and her hips into the white, and it''s also very contrasty (is that a word?) compared to the shadows of her face.', '2007-02-21 11:55:53.000000', NULL, 1),
(3389426, 472670, 47852, '<td valign="top">Unique shot for the challenge.  I''m not sure that the birds are very helpful here, I might have waited a bit until they left if that was possible.  Something about the shot feels crooked, but the horizon seems straight.. maybe from the diagonal lines of the bridge.</td>', 'Unique shot for the challenge.  I''m not sure that the birds are very helpful here, I might have waited a bit until they left if that was possible.  Something about the shot feels crooked, but the horizon seems straight.. maybe from the diagonal lines of the bridge.', '2007-02-21 11:58:12.000000', NULL, 1),
