(3392961, 472437, 72058, '<td valign="top">Very nice.  Love the lighting althought the mark inside the heart is a little distracting.</td>', 'Very nice.  Love the lighting althought the mark inside the heart is a little distracting.', '2007-02-22 08:42:43.000000', NULL, 1),
(3392977, 472143, 72058, '<td valign="top">Messy!  Great lighting.</td>', 'Messy!  Great lighting.', '2007-02-22 08:50:55.000000', NULL, 1),
(3393035, 472716, 45343, '<td valign="top">Very nice selection for DoF.  Also, very nice composition... the Stems serve as nice leading lines to guide the eye back to the main subject.  Well done.</td>', 'Very nice selection for DoF.  Also, very nice composition... the Stems serve as nice leading lines to guide the eye back to the main subject.  Well done.', '2007-02-22 09:10:04.000000', NULL, 1),
