(3405394, 471879, 38032, '<td valign="top">Spirals spin people into higher scores.  Although this is an entirely cliché overused subject I think it is successful in the variety of shapes and tones and the great deep petals that go all the way to black.</td>', 'Spirals spin people into higher scores.  Although this is an entirely cliché overused subject I think it is successful in the variety of shapes and tones and the great deep petals that go all the way to black.', '2007-02-26 07:25:52.000000', NULL, 1),
(3405407, 472541, 38032, '<td valign="top">An interesting piece of jewelry to be sure. The yellow hue, noise, and short focus hurt this though ... I''d also like to see the chain cut through the frame so that it wasn''t so centered.</td>', 'An interesting piece of jewelry to be sure. The yellow hue, noise, and short focus hurt this though ... I''d also like to see the chain cut through the frame so that it wasn''t so centered.', '2007-02-26 07:30:07.000000', NULL, 1),
