(3411388, 469327, 74500, '<td valign="top">Excellent composition -- nice use of reflection in the water drop.</td>', 'Excellent composition -- nice use of reflection in the water drop.', '2007-02-27 23:10:33.000000', NULL, 1),
(3411444, 471879, 74500, '<td valign="top">Very nicely done -- it really draws me in...</td>', 'Very nicely done -- it really draws me in...', '2007-02-27 23:22:45.000000', NULL, 1),
(3411472, 470864, 37104, '<td valign="top">Wonderful shot! The colors are great, and the profile works very well. I love the varying textures in the sky made by the clouds. My top pick.</td>', 'Wonderful shot! The colors are great, and the profile works very well. I love the varying textures in the sky made by the clouds. My top pick.', '2007-02-27 23:35:42.000000', NULL, 1),
(3411475, 472437, 37104, '<td valign="top">I''ve seen many of the paper shots, but this is so well done I''ll ignore it. The colors are momochromatic, but still vary enough to look nice. I also like the use of off-frame repetition.</td>', 'I''ve seen many of the paper shots, but this is so well done I''ll ignore it. The colors are momochromatic, but still vary enough to look nice. I also like the use of off-frame repetition.', '2007-02-27 23:36:59.000000', NULL, 1),
(3411478, 472095, 37104, '<td valign="top">I don''t like the compostition as much, but it was very well executed. I feel like the subject should be the heart, but my eye is distracted by the person in the background. My biggest critique is that it lacks a strong center of interest. But very well done.</td>', 'I don''t like the compostition as much, but it was very well executed. I feel like the subject should be the heart, but my eye is distracted by the person in the background. My biggest critique is that it lacks a strong center of interest. But very well done.', '2007-02-27 23:38:53.000000', NULL, 1),
(3411482, 468804, 37104, '<td valign="top">Wonderful depth of field and implied lines directed by the eyes of the couple. However, my favorite part of the shot is the embrace shared by the two. It isn''t particularly romantic, but it seems very genuine. Very nice shot, terrific job!</td>', 'Wonderful depth of field and implied lines directed by the eyes of the couple. However, my favorite part of the shot is the embrace shared by the two. It isn''t particularly romantic, but it seems very genuine. Very nice shot, terrific job!', '2007-02-27 23:40:48.000000', NULL, 1),
(3411486, 472385, 37104, '<td valign="top">I love the soft edges around the frame. I also like the sort of blue tint this seems to have. It isn''t as attention-getting as others, but the composition and execution are very good.<br/><br/><i>Message edited by author 2007-02-28 00:06:33.</i></td>', 'I love the soft edges around the frame. I also like the sort of blue tint this seems to have. It isn''t as attention-getting as others, but the composition and execution are very good.', '2007-02-27 23:42:02.000000', '2007-02-28 00:06:33.000000', 1),
(3411495, 472143, 37104, '<td valign="top">Awesome. Good pose, I like the choice for the background, and the chocolate driping down the hand is marvelous. It looks tasty and disgusting at the same time...</td>', 'Awesome. Good pose, I like the choice for the background, and the chocolate driping down the hand is marvelous. It looks tasty and disgusting at the same time...', '2007-02-27 23:48:05.000000', NULL, 1),
(3411496, 471879, 37104, '<td valign="top">Wonderful shadows, terrific point of view. I like that there isn''t much fancy about this; it''s very direct. Very nice job.</td>', 'Wonderful shadows, terrific point of view. I like that there isn''t much fancy about this; it''s very direct. Very nice job.', '2007-02-27 23:48:54.000000', NULL, 1),
(3411497, 472465, 37104, '<td valign="top">Great silhouettes. The sky is a little dark and dull, but the pose makes up for it. Nice job!</td>', 'Great silhouettes. The sky is a little dark and dull, but the pose makes up for it. Nice job!', '2007-02-27 23:49:54.000000', NULL, 1),
(3411498, 470980, 37104, '<td valign="top">Nice depth of field. The droplets are so clear, but I don''t think they were necessary. I would have given the same score without them.</td>', 'Nice depth of field. The droplets are so clear, but I don''t think they were necessary. I would have given the same score without them.', '2007-02-27 23:51:10.000000', NULL, 1),
(3411501, 472426, 37104, '<td valign="top">Very sharp, nice choice of background. I don''t like the foreground as out-of-focus as it is. I think it''s a bit distracting. Overall very nice shot.</td>', 'Very sharp, nice choice of background. I don''t like the foreground as out-of-focus as it is. I think it''s a bit distracting. Overall very nice shot.', '2007-02-27 23:52:13.000000', NULL, 1),
